<script setup lang="ts">
import{computed,onMounted,reactive,ref}from"vue";import{ElMessage,ElMessageBox}from"element-plus";import{Plus,Edit,Delete}from"@element-plus/icons-vue";import{api}from"@/api";import{useUserStore}from"@/stores/user";import{useProfileStore}from"@/stores/profile";import{err}from"@/utils/format";import type{Competition,Internship,Project,Skill}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";
const user=useUserStore(),store=useProfileStore(),tab=ref('basic'),saving=ref(false),error=ref(''),dialog=ref(false),kind=ref<'skill'|'project'|'competition'|'internship'>('skill'),editing=ref(-1);const p=computed(()=>store.profile);const base=reactive({name:'',school:'',major:'',grade:'',bio:'',email:'',phone:'',target_city:'',target_salary:''});const item=reactive<Record<string,any>>({});
function sync(){if(p.value)Object.assign(base,p.value)}async function load(){error.value='';try{await store.load(user.userId!,true);sync()}catch(e){error.value=err(e)}}async function saveBase(){saving.value=true;try{await api.updateUser(user.userId!,base);await load();ElMessage.success('基本信息已保存')}catch(e){ElMessage.error(err(e))}finally{saving.value=false}}
const maps={skill:'skills',project:'projects',competition:'competitions',internship:'internships'} as const;function blank(k:string){return k==='skill'?{name:'',proficiency:'熟悉',description:''}:k==='project'?{name:'',role:'',description:'',tech_stack:[],start_date:null,end_date:null}:k==='competition'?{name:'',level:'校级',award:'',description:'',competition_date:null}:{company:'',position:'',description:'',tech_stack:[],start_date:null,end_date:null}}
function open(k:typeof kind.value,index=-1){kind.value=k;editing.value=index;const source=index>=0?(p.value as any)?.[maps[k]][index]:blank(k);Object.keys(item).forEach(x=>delete item[x]);Object.assign(item,JSON.parse(JSON.stringify(source)));dialog.value=true}
async function saveItem(){if((kind.value==='skill'||kind.value==='project'||kind.value==='competition')&&!item.name||kind.value==='internship'&&!item.company){ElMessage.warning('请填写必填名称');return}const key=maps[kind.value],list=JSON.parse(JSON.stringify((p.value as any)?.[key]||[]));const clean={...item};delete clean.id;delete clean.user_id;if(editing.value>=0)list[editing.value]=clean;else list.push(clean);saving.value=true;try{await (api as any)[key](user.userId!,list);dialog.value=false;await load();ElMessage.success('经历已保存')}catch(e){ElMessage.error(err(e))}finally{saving.value=false}}
async function remove(k:typeof kind.value,index:number){await ElMessageBox.confirm('删除后将立即同步到就业档案，是否继续？','确认删除',{type:'warning'});const key=maps[k],list=JSON.parse(JSON.stringify((p.value as any)?.[key]||[]));list.splice(index,1);list.forEach((x:any)=>{delete x.id;delete x.user_id});try{await (api as any)[key](user.userId!,list);await load();ElMessage.success('已删除')}catch(e){ElMessage.error(err(e))}}onMounted(load);
</script>
<template><div><PageHeader title="我的就业档案" description="完善个人经历，为AI就业分析提供准确、持续更新的数据基础。"><el-progress :percentage="store.completeness||0" :stroke-width="8" style="width:180px"/></PageHeader><StateView :loading="store.loading&&!p" :error="error" @retry="load"><template #content><div class="profile-layout"><aside class="profile-summary"><el-avatar :size="72">{{p?.name.slice(0,1)}}</el-avatar><h3>{{p?.name}}</h3><p>{{p?.school}}</p><span>{{p?.major}} · {{p?.grade}}</span><dl><div><dt>技能</dt><dd>{{p?.skills.length}}</dd></div><div><dt>项目</dt><dd>{{p?.projects.length}}</dd></div><div><dt>竞赛/实习</dt><dd>{{(p?.competitions.length||0)+(p?.internships.length||0)}}</dd></div></dl></aside><section class="profile-editor"><el-tabs v-model="tab"><el-tab-pane label="基本信息" name="basic"><el-form label-position="top" class="form-grid"><el-form-item label="姓名"><el-input v-model="base.name"/></el-form-item><el-form-item label="学校"><el-input v-model="base.school"/></el-form-item><el-form-item label="专业"><el-input v-model="base.major"/></el-form-item><el-form-item label="年级"><el-input v-model="base.grade"/></el-form-item><el-form-item label="邮箱"><el-input v-model="base.email"/></el-form-item><el-form-item label="手机号"><el-input v-model="base.phone"/></el-form-item><el-form-item label="目标城市"><el-input v-model="base.target_city"/></el-form-item><el-form-item label="期望薪资"><el-input v-model="base.target_salary"/></el-form-item><el-form-item label="个人简介" class="full"><el-input v-model="base.bio" type="textarea" :rows="5" maxlength="5000" show-word-limit/></el-form-item></el-form><div class="form-actions"><el-button type="primary" :loading="saving" @click="saveBase">保存基本信息</el-button></div></el-tab-pane><el-tab-pane v-for="cfg in [{n:'技能',k:'skill'},{n:'项目经历',k:'project'},{n:'竞赛经历',k:'competition'},{n:'实习经历',k:'internship'}]" :key="cfg.k" :label="cfg.n" :name="cfg.k"><div class="tab-toolbar"><span>共 {{(p as any)?.[maps[cfg.k as keyof typeof maps]]?.length||0}} 项</span><el-button type="primary" :icon="Plus" @click="open(cfg.k as any)">新增</el-button></div><el-empty v-if="!(p as any)?.[maps[cfg.k as keyof typeof maps]]?.length" :description="`暂无${cfg.n}`"/><div v-else class="experience-list"><article v-for="(x,i) in (p as any)[maps[cfg.k as keyof typeof maps]]" :key="x.id||i"><div><h4>{{x.name||x.company}} <small>{{x.role||x.position||x.proficiency||x.award}}</small></h4><p>{{x.description||'暂无详细说明'}}</p><div class="tag-row"><el-tag v-for="t in x.tech_stack||[]" :key="t" size="small">{{t}}</el-tag><el-tag v-if="x.level" size="small" type="info">{{x.level}}</el-tag></div></div><div><el-button :icon="Edit" circle @click="open(cfg.k as any,i)"/><el-button :icon="Delete" circle type="danger" plain @click="remove(cfg.k as any,i)"/></div></article></div></el-tab-pane></el-tabs></section></div></template></StateView><el-dialog v-model="dialog" :title="`${editing>=0?'编辑':'新增'}${({skill:'技能',project:'项目经历',competition:'竞赛经历',internship:'实习经历'} as any)[kind]}`" width="min(620px, 92vw)"><el-form label-position="top" class="form-grid"><template v-if="kind==='skill'"><el-form-item label="技能名称"><el-input v-model="item.name"/></el-form-item><el-form-item label="熟练程度"><el-select v-model="item.proficiency"><el-option v-for="x in ['了解','熟悉','掌握','精通']" :key="x" :value="x"/></el-select></el-form-item></template><template v-if="kind==='project'"><el-form-item label="项目名称"><el-input v-model="item.name"/></el-form-item><el-form-item label="个人角色"><el-input v-model="item.role"/></el-form-item><el-form-item label="技术栈" class="full"><el-select v-model="item.tech_stack" multiple filterable allow-create default-first-option/></el-form-item></template><template v-if="kind==='competition'"><el-form-item label="竞赛名称"><el-input v-model="item.name"/></el-form-item><el-form-item label="竞赛级别"><el-input v-model="item.level"/></el-form-item><el-form-item label="获奖情况"><el-input v-model="item.award"/></el-form-item><el-form-item label="竞赛日期"><el-date-picker v-model="item.competition_date" value-format="YYYY-MM-DD"/></el-form-item></template><template v-if="kind==='internship'"><el-form-item label="公司"><el-input v-model="item.company"/></el-form-item><el-form-item label="岗位"><el-input v-model="item.position"/></el-form-item><el-form-item label="技术栈" class="full"><el-select v-model="item.tech_stack" multiple filterable allow-create default-first-option/></el-form-item></template><el-form-item label="详细说明" class="full"><el-input v-model="item.description" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveItem">保存</el-button></template></el-dialog></div></template>
